import { useActionState, useOptimistic } from 'react';

export function BookmarkToggle({ articleId, initialBookmarked }: { articleId: string; initialBookmarked: boolean }) {
  const [isBookmarked, toggleAction, isPending] = useActionState(
    async (currentState: boolean) => {
      const next = !currentState;
      await persistBookmark(articleId, next);
      return next;
    },
    initialBookmarked
  );

  const [optimisticState, setOptimistic] = useOptimistic(isBookmarked);

  return (
    <button
      disabled={isPending}
      onClick={() => {
        setOptimistic(!optimisticState);
        toggleAction();
      }}
      className="p-2 rounded-full border transition-all"
    >
      {optimisticState ? '★ Bookmarked' : '☆ Bookmark'}
    </button>
  );
}
